<script lang="ts">
    import { onMount } from 'svelte';
    import { request } from './api';
    import { AlertBanner, PageHeader, RefreshButton } from './ui';
    type Event = { id:string; event_type:string; severity:'info'|'warning'|'high'; review_status:'open'|'resolved'|'dismissed'; metadata:Record<string, unknown>; employee:string; created_at:string; resolution_note:string|null };
    type Policy={min_accuracy_meters:number;max_speed_kmh:number;retention_days:number;reviewer_user_id:string|null;require_device_attestation:boolean};
    let events=$state<Event[]>([]), policy=$state<Policy>({min_accuracy_meters:100,max_speed_kmh:180,retention_days:180,reviewer_user_id:null,require_device_attestation:false}), error=$state(''), notice=$state(''), loading=$state(true), saving=$state('');
    const labels:Record<string,string>={low_accuracy:'Akurasi GPS rendah',impossible_speed:'Perpindahan tidak masuk akal',reused_coordinates:'Koordinat berulang lintas akun',device_signal:'Sinyal perangkat'};
    async function load(){loading=true;error='';try{const [risk,settings]=await Promise.all([request<Event[]>('/v1/admin/attendance-integrity'),request<Policy>('/v1/admin/attendance-integrity/policy')]);events=risk;policy=settings;}catch(cause){error=cause instanceof Error?cause.message:'Data integritas tidak dapat dimuat.';}finally{loading=false;}}
    async function review(event:Event,status:'resolved'|'dismissed'){saving=event.id;error='';try{await request(`/v1/admin/attendance-integrity/${event.id}/review`,{method:'POST',body:JSON.stringify({status,note:''})});await load();}catch(cause){error=cause instanceof Error?cause.message:'Review tidak dapat disimpan.';}finally{saving='';}}
    async function savePolicy(){saving='policy';error='';try{await request('/v1/admin/attendance-integrity/policy',{method:'POST',body:JSON.stringify(policy)});notice='Kebijakan integritas diperbarui.';}catch(cause){error=cause instanceof Error?cause.message:'Kebijakan tidak dapat disimpan.';}finally{saving='';}}
    function detail(event:Event){return Object.entries(event.metadata).map(([key,value])=>`${key.replaceAll('_',' ')}: ${String(value)}`).join(' · ');}
    onMount(load);
</script>
<svelte:head><title>Integritas presensi · PasPapan</title></svelte:head>
<main class="workspace-page" id="main-content" tabindex="-1"><PageHeader title="Integritas presensi" description="Sinyal risiko untuk ditinjau manusia. Bukan putusan otomatis atas lokasi karyawan." backHref="/admin/dashboard"/>
<section class="panel summary"><div><strong>{events.filter(event=>event.review_status==='open').length}</strong><span>perlu review</span></div><p>Lokasi browser adalah sinyal, bukan bukti tunggal. Konfirmasi dengan kebijakan, bukti kerja, dan—untuk aplikasi native—attestation perangkat.</p><RefreshButton onclick={load} label="Muat ulang"/></section>
{#if error}<AlertBanner variant="error">{error}</AlertBanner>{/if}{#if notice}<AlertBanner variant="success">{notice}</AlertBanner>{/if}
<section class="panel policy"><h2>Kebijakan & privasi</h2><p>Atur ambang sinyal risiko. Attestation hanya dapat dipenuhi oleh aplikasi mobile native yang mengirim bukti perangkat tervalidasi.</p><form novalidate onsubmit={(event)=>{event.preventDefault();void savePolicy();}}><label>Akurasi GPS minimum (meter)<input bind:value={policy.min_accuracy_meters} type="number" min="1" max="10000"/></label><label>Batas kecepatan (km/jam)<input bind:value={policy.max_speed_kmh} type="number" min="1" max="2000"/></label><label>Retensi sinyal (hari)<input bind:value={policy.retention_days} type="number" min="1" max="3650"/></label><label class="check"><input bind:checked={policy.require_device_attestation} type="checkbox"/> Wajibkan device attestation untuk aplikasi mobile</label><button disabled={saving==='policy'}>{saving==='policy'?'Menyimpan…':'Simpan kebijakan'}</button></form></section>
<section class="panel list" aria-busy={loading}>{#if !events.length && !loading}<p class="muted">Belum ada sinyal risiko yang tercatat.</p>{/if}{#each events as event (event.id)}<article><div class="title"><span class:high={event.severity==='high'} class:warning={event.severity==='warning'} class:info={event.severity==='info'}>{event.severity}</span><div><strong>{labels[event.event_type]??event.event_type}</strong><p>{event.employee} · {new Date(event.created_at).toLocaleString('id-ID')}</p></div><em>{event.review_status}</em></div><p class="detail">{detail(event)}</p>{#if event.review_status==='open'}<div class="actions"><button class="secondary" disabled={saving===event.id} onclick={()=>review(event,'dismissed')}>Dismiss</button><button disabled={saving===event.id} onclick={()=>review(event,'resolved')}>Selesaikan</button></div>{:else if event.resolution_note}<p class="muted">{event.resolution_note}</p>{/if}</article>{/each}</section></main>
<style>.workspace-page{display:grid;gap:12px}.panel{padding:16px;border-radius:var(--radius)}.summary{display:flex;align-items:center;gap:16px}.summary div{display:grid;min-width:100px}.summary strong{font-size:28px}.summary span,.summary p,.muted,.policy p{font-size:12px;color:var(--muted)}.summary p,.policy p{margin:0;flex:1}.policy{display:grid;gap:10px}.policy form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.policy label{display:grid;gap:4px;font-size:11px;font-weight:700}.policy .check{display:flex;align-items:center;grid-column:span 2}.policy button{align-self:end}.list{display:grid;gap:8px}.list article{border:1px solid var(--line);border-radius:var(--radius-sm);padding:12px}.title{display:flex;align-items:start;gap:9px}.title strong{font-size:13px}.title p,.detail{margin:4px 0 0;color:var(--muted);font-size:12px}.title em{margin-left:auto;font-size:11px;font-style:normal;color:var(--muted);text-transform:capitalize}.title span{font-size:10px;font-weight:700;text-transform:uppercase;padding:3px 6px;border-radius:var(--radius);background:var(--surface-alt)}.title span.high{color:var(--danger)}.title span.warning{color:#b7791f}.title span.info{color:var(--accent)}.detail{text-transform:none}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:9px}.secondary{background:var(--surface-alt);color:var(--text);border:1px solid var(--line)}@media(max-width:640px){.summary{align-items:flex-start;flex-wrap:wrap}.summary p{order:3;flex-basis:100%}.policy form{grid-template-columns:1fr}.policy .check{grid-column:auto}}</style>
